'use strict';
// Contracts for the Phase 2 punycode drills bundle (oracle-sft-drills.json),
// generated by scripts/prepare-finetune-data.js → buildDrillRecords().
const { test } = require('node:test');
const assert = require('node:assert');
const { domainToASCII } = require('node:url');

const { buildDrillRecords } = require('../scripts/prepare-finetune-data.js');

const { records, report } = buildDrillRecords();

test('drills: meaningful volume across the owned-domain set', () => {
  assert.ok(records.length >= 800, `expected >= 800 drill records, got ${records.length}`);
  assert.ok(report.domainPairs >= 300, `expected >= 300 domains, got ${report.domainPairs}`);
  assert.strictEqual(report.mismatches.length, 0, `conversion failures: ${report.mismatches}`);
});

test('drills: sharegpt shape — alternate human/gpt, end on gpt', () => {
  for (const rec of records) {
    const convo = rec.conversations;
    assert.ok(Array.isArray(convo) && convo.length === 2, 'exactly one turn pair');
    assert.strictEqual(convo[0].from, 'human');
    assert.strictEqual(convo[1].from, 'gpt');
    for (const m of convo) {
      assert.strictEqual(typeof m.value, 'string');
      assert.ok(m.value.trim().length > 0, 'no empty values');
    }
  }
});

test('drills: every encoding answer is a valid self-consistent punycode domain', () => {
  const enc = records.filter((r) =>
    r.conversations[0].value.startsWith('What is the punycode form of')
  );
  assert.ok(enc.length >= 300, `expected >= 300 encoding drills, got ${enc.length}`);
  for (const rec of enc) {
    const answer = rec.conversations[1].value;
    if (answer.includes('pure ASCII')) continue; // trap pair
    const m = answer.match(/^(xn--[a-z0-9-]+(\.[a-z0-9-]+)+)/i);
    assert.ok(m, `answer has no punycode domain: ${answer}`);
    assert.strictEqual(domainToASCII(m[1]), m[1], `punycode does not round-trip: ${m[1]}`);
  }
});

test('drills: the graded checks — exact apóllōn and zeús strings present', () => {
  const find = (q) => records.find((r) => r.conversations[0].value === q)?.conversations[1].value;
  assert.strictEqual(find('What is the punycode form of apóllōn.com?'), 'xn--aplln-1ta64d.com');
  assert.strictEqual(find('What is the punycode form of zeús.com?'), 'xn--zes-9na.com');
});

test('drills: no retired tier language anywhere', () => {
  const joined = JSON.stringify(records);
  assert.ok(!/Tier 1|Tier 2|dual-tier/i.test(joined), 'tier language leaked into drills');
});

test('drills: no zero-width characters, no exact duplicates', () => {
  const seen = new Set();
  for (const rec of records) {
    const text = JSON.stringify(rec);
    assert.ok(!/[\u200B-\u200D\uFEFF]/.test(text), 'zero-width character present');
    assert.ok(!seen.has(text), 'exact duplicate drill');
    seen.add(text);
  }
});
